        message = f"{len(self._errors)} validation errors:\n"
        for err in self._errors:
            message += f"  {err}\n"
        if self.endpoint_metadata:
            meta = self.endpoint_metadata
            message += (
                f"Endpoint: {meta['method']} {meta['route']} "
                f"({meta['function_name']} at {meta['file']}:{meta['line']})\n"
            )
        return message

